"""A proof the browser built must verify on this server — roadmap P9-b.

test_channel_state.py holds this server's encoding to the Solidity vectors, and
proof-of-facilitation/browser-test does the same for the browser. Neither proves
the two agree over the actual object that travels between them: an award proof,
which is a wire-form state plus two signatures in party order.

That object is where a disagreement would hurt and not show. A field the browser
spells differently, or signatures assembled into the wrong slots, produces
awards that silently stop verifying — safe, because the failure direction is
refusal, but indistinguishable from a user error and impossible to attribute.

So the fixture is generated by the real browser client, and checked here by the
real server code. Signature recovery is done with the renderer's ethers (v5),
because that is what actually recovers these in production.

Skips when node or the installs are absent: the golden-vector tests already hold
each side to the contract on its own.
"""

import json
import os
import pathlib
import subprocess
import sys
import unittest

BACKEND = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if BACKEND not in sys.path:
    sys.path.insert(0, BACKEND)

from services.channel_state import (  # noqa: E402
    check_signature_shape,
    decode_state,
    derive_channel_id,
    digest_of,
    is_party_a,
    received_by,
    sort_parties,
)

REPO = pathlib.Path(BACKEND).parent
POF = REPO / "proof-of-facilitation"
FIXTURE = POF / "browser-test" / "award-proof.mjs"
FRONTEND = REPO / "frontend"

AXON = 10 ** 18


def _node():
    from shutil import which
    return which("node")


def _load_fixture():
    node = _node()
    if node is None:
        raise unittest.SkipTest("node is not installed")
    if not FIXTURE.exists():
        raise unittest.SkipTest("award-proof.mjs is missing")
    if not (POF / "node_modules" / "ethers").exists():
        raise unittest.SkipTest("ethers is not installed in proof-of-facilitation")
    out = subprocess.run([node, str(FIXTURE)], cwd=str(POF),
                         capture_output=True, check=True)
    return json.loads(out.stdout)


def _recover_with_renderer_ethers(digest_hex, signature):
    """Recover a digest signature the way RENDERER_HOST/verify/digest does.

    The same ethers v5 `verifyMessage(arrayify(digest), sig)` the sidecar runs,
    invoked directly so the test does not need the sidecar up. Using the string
    form here instead of arrayify would recover a different, entirely
    plausible-looking address — which is the whole reason /verify/digest is a
    separate endpoint from /verify/wallet.
    """
    node = _node()
    if node is None or not (FRONTEND / "node_modules" / "ethers").exists():
        raise unittest.SkipTest("the renderer's ethers is not installed")
    script = (
        "const {ethers}=require('ethers');"
        "const d=process.argv[1], s=process.argv[2];"
        "console.log(ethers.utils.verifyMessage(ethers.utils.arrayify(d), s));"
    )
    out = subprocess.run(
        [node, "-e", script, "0x" + digest_hex, signature],
        cwd=str(FRONTEND), capture_output=True, check=True)
    return out.stdout.decode().strip().lower()


class AwardProofInterop(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.fx = _load_fixture()

    def test_the_channel_id_agrees(self):
        # If the two sides derived this differently they would not even be
        # talking about the same channel — and the party ordering, which decides
        # whose balance counts, would be undefined between them.
        derived = derive_channel_id(self.fx["giver"], self.fx["author"]).hex()
        self.assertEqual(derived, self.fx["channel_id"].replace("0x", ""))
        self.assertEqual(
            is_party_a(self.fx["giver"], self.fx["author"]), self.fx["giver_is_a"])

    def test_the_digest_agrees(self):
        for name, case in self.fx["cases"].items():
            with self.subTest(case=name):
                state = decode_state(case["proof"]["state"])
                digest = digest_of(state, self.fx["chain_id"], self.fx["contract"])
                self.assertEqual("0x" + digest.hex(), case["digest"])

    def test_both_signatures_recover_to_the_right_parties(self):
        party_a, party_b = sort_parties(self.fx["giver"], self.fx["author"])
        for name, case in self.fx["cases"].items():
            with self.subTest(case=name):
                state = decode_state(case["proof"]["state"])
                digest = digest_of(state, self.fx["chain_id"], self.fx["contract"]).hex()

                sig_a = check_signature_shape(case["proof"]["sig_a"])
                sig_b = check_signature_shape(case["proof"]["sig_b"])

                self.assertEqual(_recover_with_renderer_ethers(digest, sig_a), party_a)
                self.assertEqual(_recover_with_renderer_ethers(digest, sig_b), party_b)

    def test_the_state_carries_what_the_author_received(self):
        author_is_a = is_party_a(self.fx["author"], self.fx["giver"])
        paid = decode_state(self.fx["cases"]["paid"]["proof"]["state"])
        self.assertEqual(received_by(paid, author_is_a), 25 * AXON)

    def test_a_checkpoint_does_not_change_what_was_received(self):
        # The author drew the money out. It is still money they received, and a
        # ledger that thought otherwise would credit the awards a second time.
        author_is_a = is_party_a(self.fx["author"], self.fx["giver"])
        drawn = decode_state(self.fx["cases"]["checkpointed"]["proof"]["state"])
        self.assertEqual(received_by(drawn, author_is_a), 25 * AXON)

    def test_a_tampered_state_does_not_verify(self):
        """The property the whole design rests on.

        Raising the author's balance after signing must break the digest, or a
        giver could sign a small payment and claim a large one.
        """
        case = self.fx["cases"]["paid"]
        honest = decode_state(case["proof"]["state"])
        honest_digest = digest_of(honest, self.fx["chain_id"], self.fx["contract"])

        tampered = dict(case["proof"]["state"])
        key = "balance_a" if self.fx["giver_is_a"] is False else "balance_b"
        tampered[key] = str(int(tampered[key]) + 100 * AXON)
        forged = digest_of(decode_state(tampered), self.fx["chain_id"], self.fx["contract"])

        self.assertNotEqual(honest_digest, forged)

    def test_a_state_from_another_deployment_does_not_verify(self):
        # The chain id and contract are inside the digest so a state signed for
        # one deployment cannot be replayed against another. That is exactly why
        # the server takes them from configuration and never from the claim.
        case = self.fx["cases"]["paid"]
        state = decode_state(case["proof"]["state"])
        elsewhere = digest_of(state, 1, "0xae70526931FF460894133201f6C8cA91bbA0E177")
        self.assertNotEqual("0x" + elsewhere.hex(), case["digest"])


if __name__ == "__main__":
    unittest.main()
